/*
 * A140708  Prime chain of 128 terms, including 104 distinct primes,
 *          consisting of the output of eight equations that alternate
 *          sequentially within a procedural expression of a single
 *          polynomial. The equations are either subsequences of x^2 - 79x +
 *          1601 or transforms with one exception: 100x^2 - 2260x + 1295...
 * https://oeis.org/A140708
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, more, uned
 * Formula:   OEIS A140708 * Prime chain of 128 terms generated by cyclically
 *            applying eight * quadratic polynomials: * Q1(x) = 25x^2 – 1185x
 *            + 14083 (indices 1,5 mod 8) * Q2(x) = 25x^2 – 775x + 6047
 *            (indices 3,7 mod 8) * Q3(x) = 100x^2 – 2280x + 13159 (index 4
 *            mod 8) * Q4(x) = 100x^2 – 4160x + 43427 (index 6...
 * Range:     u8 none, u16 n <= 38, u32 n <= 38, u64 n <= 38, u128 n <= 38,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    idx_t r = n % 8;
    switch (r) {
        case 1:
        case 5: {
            seq_t x = (seq_t)(n - 1) / 4;
            return 25 * x * x - 1185 * x + 14083;
        }
        case 3:
        case 7: {
            seq_t x = (seq_t)(n - 3) / 4;
            return 25 * x * x - 775 * x + 6047;
        }
        case 4: {
            seq_t x = (seq_t)(n - 4) / 8;
            return 100 * x * x - 2280 * x + 13159;
        }
        case 6: {
            seq_t x = (seq_t)(n - 6) / 8;
            return 100 * x * x - 4160 * x + 43427;
        }
        case 2: {
            seq_t x = (seq_t)(n - 2) / 8;
            return 100 * x * x - 2360 * x + 14087;
        }
        case 0: /* n % 8 == 0 */
        {
            seq_t x = (seq_t)(n - 8) / 8;
            return 100 * x * x - 2260 * x + 12959;
        }
    }
    return 0; /* unreachable but satisfies the compiler */
}
